/** Initialize EntryPointContract
  *
  * guarantee INITIAL_POWER_FACTS_SAFE
  * @param api_power_to_authorization outgoing data port
  * @param api_power_to_lifecycle outgoing data port
  */
pub fn initialize_INITIAL_POWER_FACTS_SAFE(
  api_power_to_authorization: Vehicle_Start_Readiness_Recovery_Supervisor::PowerFacts,
  api_power_to_lifecycle: Vehicle_Start_Readiness_Recovery_Supervisor::PowerFacts) -> bool
{
  (api_power_to_authorization.evidenceTrusted == false) &
    (api_power_to_authorization.availableForSupervision == false) &
    (api_power_to_lifecycle.evidenceTrusted == false) &
    (api_power_to_lifecycle.availableForSupervision == false)
}

