/** Compute Entrypoint Contract
  *
  * guarantee POWER_FACT_DERIVATION
  * @param api_power_observation incoming data port
  * @param api_power_to_authorization outgoing data port
  * @param api_power_to_lifecycle outgoing data port
  */
pub fn compute_spec_POWER_FACT_DERIVATION_guarantee(
  api_power_observation: Vehicle_Start_Readiness_Recovery_Supervisor::PowerObservation,
  api_power_to_authorization: Vehicle_Start_Readiness_Recovery_Supervisor::PowerFacts,
  api_power_to_lifecycle: Vehicle_Start_Readiness_Recovery_Supervisor::PowerFacts) -> bool
{
  ((api_power_observation == Vehicle_Start_Readiness_Recovery_Supervisor::PowerObservation::Available) &
    api_power_to_authorization.evidenceTrusted &
    api_power_to_authorization.availableForSupervision |
    (api_power_observation == Vehicle_Start_Readiness_Recovery_Supervisor::PowerObservation::Unavailable) &
      api_power_to_authorization.evidenceTrusted &
      (api_power_to_authorization.availableForSupervision == false) |
    (api_power_observation == Vehicle_Start_Readiness_Recovery_Supervisor::PowerObservation::Invalid) &
      (api_power_to_authorization.evidenceTrusted == false) &
      (api_power_to_authorization.availableForSupervision == false)) &
    (api_power_to_lifecycle.evidenceTrusted == api_power_to_authorization.evidenceTrusted) &
    (api_power_to_lifecycle.availableForSupervision == api_power_to_authorization.availableForSupervision)
}

